import {
  Button as AriaButton,
  Collection,
  Tree as AriaTree,
  TreeHeader as AriaTreeHeader,
  TreeItem as AriaTreeItem,
  TreeItemContent,
  TreeLoadMoreItem as AriaTreeLoadMoreItem,
  TreeSection as AriaTreeSection,
} from "react-aria-components";
import type {
  GridListSectionProps as AriaTreeSectionProps,
  TreeItemProps as AriaTreeItemProps,
  TreeLoadMoreItemProps as AriaTreeLoadMoreItemProps,
  TreeProps as AriaTreeProps,
} from "react-aria-components";
import { ChevronDown } from "./icons";
import { createContext, useContext } from "react";
import type { ComponentProps, CSSProperties, ReactNode, Ref } from "react";
import "./Tree.css";

// react-aria-components doesn't export a standalone `GridListHeaderProps` type
// (the type TreeHeader actually uses); derive it from the component itself.
type AriaTreeHeaderProps = Omit<ComponentProps<typeof AriaTreeHeader>, "ref">;

type TreeItemStyle = AriaTreeItemProps["style"];
type TreeItemStyleRenderProps = Parameters<Exclude<TreeItemStyle, CSSProperties | undefined>>[0];

export type TreeSize = "small" | "medium" | "large";

// `size` is set once on the Tree, which renders `data-size` for the CSS relay; RAC hands a TreeItem
// no channel to read it, so this context carries it to the rows' type roles.
const TreeSizeContext = createContext<TreeSize>("medium");

// One rung below the items it heads, with `small` as the floor: CONTRASTIVE, per
// naming-convention.md.
const HEADER_RUNG: Record<TreeSize, TreeSize> = { small: "small", medium: "small", large: "medium" };

// Generic in its item type, like every other collection here (`ListBox`, `GridList`, `Table*`,
// `MenuSection`, `Breadcrumb`). Pinned to `AriaTreeProps<object>`, the render callback's
// parameter would be `object` and every `item.id` / `item.name` a type error in the consumer.
export interface TreeProps<T extends object = object>
  extends Omit<AriaTreeProps<T>, "className"> {
  /**
   * Row size: each row's padding, level indent and chevron, and its text (`body-<size>`), with the
   * section header one label rung below. `small` is for a dense tool panel.
   *
   * @default "medium"
   */
  size?: TreeSize;
  /** Additional class. sd-tree is always retained. */
  className?: string;
  /** Passed to the root tree DOM element. */
  ref?: Ref<HTMLDivElement>;
}

export function Tree<T extends object = object>({
  size = "medium",
  className,
  ref,
  renderEmptyState,
  ...props
}: TreeProps<T>) {
  return (
    <TreeSizeContext.Provider value={size}>
      <AriaTree
        {...props}
        /* An empty state given as words is a text part of its own: a bare string took no type role,
           so it stood at 0 while every other text stands one inset in (component-contract.md §6
           rule 8). Medium at every size, as a collection's empty message is (§7), muted as an empty
           line is (text colour roles, row 4). Words are wrapped; an element the consumer drew (a
           ComboBox's own empty part) is its own. */
        renderEmptyState={
          renderEmptyState &&
          ((p) => {
            const empty = renderEmptyState(p);
            return typeof empty === "string" || typeof empty === "number" ? <div className="sd-tree__empty sd-type-body-medium">{empty}</div> : empty;
          })
        }
        ref={ref}
        data-size={size}
        className={className ? `sd-tree ${className}` : "sd-tree"}
      />
    </TreeSizeContext.Provider>
  );
}

export interface TreeItemProps
  extends Omit<AriaTreeItemProps, "className" | "children" | "style"> {
  /** Item label content. */
  title: ReactNode;
  /** Nested TreeItem children. */
  children?: ReactNode;
  /** Additional class. sd-tree__item is always retained. */
  className?: string;
  /** Additional style, composed with the item level indentation variable. */
  style?: TreeItemStyle;
  /** Passed to the underlying tree item DOM element. */
  ref?: Ref<HTMLDivElement>;
}

export function TreeItem({
  title,
  children,
  className,
  style,
  ref,
  ...props
}: TreeItemProps) {
  const size = useContext(TreeSizeContext);
  return (
    <AriaTreeItem
      {...props}
      ref={ref}
      className={
        className
          ? `sd-tree__item sd-type-body-${size} ${className}`
          : `sd-tree__item sd-type-body-${size}`
      }
      style={(renderProps) => ({
        ...resolveTreeItemStyle(style, renderProps),
        // React Aria numbers a ROOT item `level: 1`, so passing it straight through would
        // indent every root item by one step it has no parent for. Zero-based, a root label sits
        // one chevron column in from its section header, which is exactly the column the header
        // does not have. The step is the DEPTH, so the first depth is none.
        "--sd-tree-item-level": renderProps.level - 1,
      } as CSSProperties)}
    >
      <TreeItemContent>
        {({ isExpanded, hasChildItems }) => (
          <>
            <AriaButton
              slot="chevron"
              className="sd-tree__chevron"
              data-expanded={isExpanded || undefined}
              data-has-child-items={hasChildItems || undefined}
            >
              <span aria-hidden="true"><ChevronDown size="1em" /></span>
            </AriaButton>
            {title}
          </>
        )}
      </TreeItemContent>
      {children}
    </AriaTreeItem>
  );
}

export interface TreeSectionProps<T extends object = object>
  extends Omit<AriaTreeSectionProps<T>, "className" | "children"> {
  /** Optional section-header text — when passed, renders the header automatically (the same convenience as ListBoxSection). */
  title?: string;
  /** TreeItem list or dynamic collection renderer. */
  children?: AriaTreeSectionProps<T>["children"];
  /** Additional class (optional). sd-tree__section is always preserved. */
  className?: string;
  /** Forwarded to the underlying DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function TreeSection<T extends object = object>({
  title,
  className,
  ref,
  children,
  ...props
}: TreeSectionProps<T>) {
  const size = useContext(TreeSizeContext);
  return (
    <AriaTreeSection
      {...props}
      ref={ref}
      className={className ? `sd-tree__section ${className}` : "sd-tree__section"}
    >
      {title && (
        <AriaTreeHeader className={`sd-tree__section-header sd-type-label-${HEADER_RUNG[size]}`}>
          {title}
        </AriaTreeHeader>
      )}
      {typeof children === "function" ? <Collection>{children}</Collection> : children}
    </AriaTreeSection>
  );
}

export interface TreeHeaderProps extends Omit<AriaTreeHeaderProps, "className"> {
  /** Additional class (optional). sd-tree__section-header is always preserved. */
  className?: string;
}

export function TreeHeader({ className, ...props }: TreeHeaderProps) {
  const size = useContext(TreeSizeContext);
  return (
    <AriaTreeHeader
      {...props}
      className={
        className
          ? `sd-tree__section-header sd-type-label-${HEADER_RUNG[size]} ${className}`
          : `sd-tree__section-header sd-type-label-${HEADER_RUNG[size]}`
      }
    />
  );
}

export interface TreeLoadMoreItemProps
  extends Omit<AriaTreeLoadMoreItemProps, "className" | "children"> {
  /** Loading-row content — required; the .tsx bakes no default text (contract §7b: no
   *  default content, and a hardcoded "Loading…" would ship untranslated English). */
  children: AriaTreeLoadMoreItemProps["children"];
  /** Additional class. sd-tree__load-more is always retained. */
  className?: string;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function TreeLoadMoreItem({
  children,
  className,
  isLoading = true,
  ...props
}: TreeLoadMoreItemProps) {
  const size = useContext(TreeSizeContext);
  return (
    <AriaTreeLoadMoreItem
      {...props}
      isLoading={isLoading}
      className={
        className
          ? `sd-tree__load-more sd-type-caption-${size} ${className}`
          : `sd-tree__load-more sd-type-caption-${size}`
      }
    >
      {children}
    </AriaTreeLoadMoreItem>
  );
}

function resolveTreeItemStyle(
  style: TreeItemStyle | undefined,
  renderProps: TreeItemStyleRenderProps,
) {
  return typeof style === "function" ? style(renderProps) : style;
}

.sd-tree {
  display: flex;
  flex-direction: column;
  gap: var(--sd-tree-gap);
  color: var(--sd-tree-foreground);
}

/* `size` is set once on the Tree root as `data-size`. Each sized token resolves to a `-current`
   value there and inherits down, so one attribute sets every row and the load-more footer together. `medium` is the default rung. Because the relay resolves at the root,
   override a sized token on the Tree, not on one item. */
.sd-tree {
  --sd-tree-item-padding-block-current: var(--sd-tree-item-padding-block-medium);
  --sd-tree-item-gap-current: var(--sd-tree-item-gap-medium);
  --sd-tree-indent-step-current: var(--sd-tree-indent-step-medium);
  --sd-tree-chevron-size-current: var(--sd-tree-chevron-size-medium);
  --sd-tree-load-more-padding-block-current: var(--sd-tree-load-more-padding-block-medium);
  --sd-tree-load-more-padding-inline-current: var(--sd-tree-load-more-padding-inline-medium);
}
.sd-tree[data-size="small"] {
  --sd-tree-item-padding-block-current: var(--sd-tree-item-padding-block-small);
  --sd-tree-item-gap-current: var(--sd-tree-item-gap-small);
  --sd-tree-indent-step-current: var(--sd-tree-indent-step-small);
  --sd-tree-chevron-size-current: var(--sd-tree-chevron-size-small);
  --sd-tree-load-more-padding-block-current: var(--sd-tree-load-more-padding-block-small);
  --sd-tree-load-more-padding-inline-current: var(--sd-tree-load-more-padding-inline-small);
}
.sd-tree[data-size="large"] {
  --sd-tree-item-padding-block-current: var(--sd-tree-item-padding-block-large);
  --sd-tree-item-gap-current: var(--sd-tree-item-gap-large);
  --sd-tree-indent-step-current: var(--sd-tree-indent-step-large);
  --sd-tree-chevron-size-current: var(--sd-tree-chevron-size-large);
  --sd-tree-load-more-padding-block-current: var(--sd-tree-load-more-padding-block-large);
  --sd-tree-load-more-padding-inline-current: var(--sd-tree-load-more-padding-inline-large);
}

.sd-tree__item {
  display: flex;
  align-items: center;
  gap: var(--sd-tree-item-gap-current);
  min-height: var(--sd-tree-item-min-height);
  padding-block: var(--sd-tree-item-padding-block-current);
  /* A row whose only paint is its fill, so its content sits at 0 on the one start line and the fill
     bleeds past it instead (component-contract.md §6 rule 8; Collapsible is the reference shape).
     The per-level indent is the only inline padding: it is the row's place in the hierarchy. */
  padding-inline-start: calc(var(--sd-tree-item-level, 0) * var(--sd-tree-indent-step-current));
  color: var(--sd-tree-foreground);
  /* The fill lives on the ::before so it can bleed; the box itself paints nothing. */
  background: transparent;
  /* The fill the ::before paints: the rest fill, or the selected or drop-target fill below. */
  --sd-tree-item-fill-current: var(--sd-tree-item-background);
  border-radius: var(--sd-tree-item-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  cursor: pointer;
  user-select: none;
  position: relative;
  isolation: isolate;
  /* The wash each state lays over this part: the surface wash, or over a fill the one named for that
     fill, which goes away from its inks (contrast-contract.mjs § the state layer over a fill). */
  --sd-tree-item-state-hover-current: var(--sd-state-hover);
  --sd-tree-item-state-pressed-current: var(--sd-state-pressed);
}

/* The rest, selected and drop-target fill, on a layer rather than the box so it bleeds with the
   state layer. Under the content: the root isolates, so -1 stays inside it (component-contract.md § 6). */
.sd-tree__item::before {
  content: "";
  position: absolute;
  inset-block: 0;
  inset-inline: calc(-1 * var(--sd-tree-item-state-layer-overhang));
  border-radius: inherit;
  corner-shape: inherit;
  background: var(--sd-tree-item-fill-current);
  pointer-events: none;
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}

/* Interaction state-layer: hover/pressed tint composites over rest/selected/
   drop-target fill via a pointer-events-none ::after overlay (ADR-0009). Later in tree order than
   the ::before, so it paints above it at the same z-index, and it bleeds by the same overhang. */
.sd-tree__item::after {
  content: "";
  position: absolute;
  inset-block: 0;
  inset-inline: calc(-1 * var(--sd-tree-item-state-layer-overhang));
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-tree__item[data-hovered]::after,
.sd-tree__item[data-focused]::after {
  background: var(--sd-tree-item-state-hover-current);
}
.sd-tree__item[data-pressed]::after {
  background: var(--sd-tree-item-state-pressed-current);
}

.sd-tree__item[data-selected] {
  --sd-tree-item-fill-current: var(--sd-tree-item-background-selected);
  --sd-tree-item-state-hover-current: var(--sd-state-hover-selected);
  --sd-tree-item-state-pressed-current: var(--sd-state-pressed-selected);
}

.sd-tree__item[data-focused] {
  outline: none;
}

/* On the ::after, so the ring traces the same bled shape the fill and the wash draw; on the box it
   would hug the content, narrower than what lights up. `z-index: 1` lifts it over a flush
   neighbour's bled layers, which a later sibling would otherwise paint over it. */
.sd-tree__item[data-focus-visible] {
  z-index: 1;
}
.sd-tree__item[data-focus-visible]::after {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-tree__item[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

.sd-tree__item[data-dragging] {
  opacity: var(--sd-state-dragging);
}

.sd-tree__item[data-drop-target] {
  --sd-tree-item-fill-current: var(--sd-tree-item-background-drop-target);
}

.sd-tree__chevron {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 var(--sd-tree-chevron-size-current);
  width: var(--sd-tree-chevron-size-current);
  height: var(--sd-tree-chevron-size-current);
  /* The slot owns the glyph scale, so a consumer's `size="1em"` chevron lands on this box. Without
     it `1em` resolves against the row's inherited `body-small` and draws 14px inside a declared 16
     in some brands. Same contract as the NavItem icon slot
     and Button: the container sets the icon font-size, the icon is 1em. Border and padding are both
     zero here, so the content box IS this token. */
  font-size: var(--sd-tree-chevron-size-current);
  padding: var(--sd-tree-chevron-padding);
  color: var(--sd-tree-chevron-foreground);
  background: var(--sd-tree-chevron-background);
  border: 0;
  transform: rotate(-90deg);
  transition: transform var(--sd-duration-moderate) var(--sd-easing-standard);
}

.sd-tree__chevron[data-expanded] {
  transform: rotate(0deg);
}

.sd-tree__chevron:not([data-has-child-items]) {
  visibility: hidden;
}

@media (prefers-reduced-motion: reduce) {
  .sd-tree__chevron {
    transition: none;
  }
}

/* `section-gap` parts one SECTION from the next and nothing else. Spent as the section's own
   flex `gap` it landed between EVERY child, which pushed the header away from the group it
   labels and toward the group above it — measured in every brand, the header sat closer to the
   previous section's last row than to the first row it names. It also re-spaced the rows
   themselves, so a list's row rhythm changed the moment it gained a header. Rows inside a
   section are now parted by whatever parts rows in a section-less list, which is the root gap. */
.sd-tree__section {
  display: flex;
  flex-direction: column;
  gap: var(--sd-tree-gap);
}

/* ADJACENCY is an assumption, not a guarantee. React Aria's `Virtualizer` wraps each node in a
   `VirtualizerItem`, which would split this pair and silently drop the separation. Nothing under
   `src/**` uses it and no component exposes it, so nothing rendered is wrong; a cold review found
   no selector correct under both shapes at no cost, because spacing an absolutely positioned
   wrapper fights the virtualizer's own layout. Re-measure here first if virtualization is ever
   offered. */
.sd-tree__section + .sd-tree__section {
  margin-block-start: var(--sd-tree-section-gap);
}

.sd-tree__section-header {
  /* At 0 inline, on the start line the rows' content shares. */
  padding-block: var(--sd-tree-section-header-padding-block-start) var(--sd-tree-section-header-padding-block-end);
  color: var(--sd-tree-section-header-foreground);
}

.sd-tree__load-more {
  display: flex;
  justify-content: center;
  padding-block: var(--sd-tree-load-more-padding-block-current);
  padding-inline: var(--sd-tree-load-more-padding-inline-current);
  color: var(--sd-tree-load-more-foreground);
}

/* The empty-state message (`renderEmptyState`): its own text part, so it takes a type role and the
   text inset like every other text, in the supporting ink of an empty line. */
.sd-tree__empty {
  color: var(--sd-tree-empty-foreground);
}
